body.script:
const owner = 'lotsacookie;
const repo = 'kstuff';
const filePath = 'Pages/gfn/assets/main.js';

const apiUrl = new URL('https://api.github.com/repos/' + owner + '/' + repo + '/commits');
apiUrl.searchParams.append('path', filePath);
apiUrl.searchParams.append('per_page', '1');

fetch(apiUrl)
    .then(function(res) { 
        return res.json(); 
    })
    .then(function(data) {
        if (data) {
            if (data[0]) {
                if (data[0].sha) {
                    const sha = data[0].sha;
                    const scriptUrl = 'https://cdn.jsdelivr.net/gh/' + owner + '/' + repo + '@' + sha + '/' + filePath;
                    const script = document.createElement('script');
                    script.src = scriptUrl;
                    document.body.appendChild(script);
                }
            }
        }
    })
    .catch(function(err) { 
        console.error('Fetch error:', err); 
    });
